begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id) values('de910000-0000-4000-8000-000000000001'),('de910000-0000-4000-8000-000000000002');
insert into profiles(id) values('de910000-0000-4000-8000-000000000001'),('de910000-0000-4000-8000-000000000002');
insert into branches(id,code,name) values('de910000-0000-4000-8000-000000000011','INV-TEST-A','Inventory test A'),('de910000-0000-4000-8000-000000000012','INV-TEST-B','Inventory test B');
insert into user_roles(user_id,role_id) select 'de910000-0000-4000-8000-000000000001',id from roles where code='SUPER_ADMIN';
insert into roles(code,name) values('INVENTORY_TEST_ROLE','Synthetic inventory role');
insert into role_permissions(role_id,permission_id) select r.id,p.id from roles r cross join permissions p where r.code='INVENTORY_TEST_ROLE' and p.code in('inventory.view','inventory.manage');
insert into user_roles(user_id,role_id,branch_id) select 'de910000-0000-4000-8000-000000000002',id,'de910000-0000-4000-8000-000000000011' from roles where code='INVENTORY_TEST_ROLE';
select set_config('request.jwt.claim.sub','de910000-0000-4000-8000-000000000001',true);
set local role authenticated;
select lives_ok($$select create_inventory_item('INV-BOOK','Book','Books','copy')$$,'Create catalogue item');
select lives_ok($$select post_inventory_movement('de910000-0000-4000-8000-000000000021',id,'de910000-0000-4000-8000-000000000011','RECEIPT',10,'Initial receipt') from inventory_items where code='INV-BOOK'$$,'Receive ten');
select lives_ok($$select post_inventory_movement('de910000-0000-4000-8000-000000000021',id,'de910000-0000-4000-8000-000000000011','RECEIPT',10,'Initial receipt') from inventory_items where code='INV-BOOK'$$,'Exact retry succeeds');
select is((select count(*) from inventory_entries where movement_id='de910000-0000-4000-8000-000000000021'),1::bigint,'No duplicate receipt');
select throws_ok($$select post_inventory_movement('de910000-0000-4000-8000-000000000021',id,'de910000-0000-4000-8000-000000000011','RECEIPT',11,'Initial receipt') from inventory_items where code='INV-BOOK'$$,'P0001','Inventory request payload mismatch','Same request cannot change quantity');
select lives_ok($$select post_inventory_movement('de910000-0000-4000-8000-000000000022',id,'de910000-0000-4000-8000-000000000011','OUTBOUND',2,'Issue books') from inventory_items where code='INV-BOOK'$$,'Outbound');
select lives_ok($$select post_inventory_movement('de910000-0000-4000-8000-000000000023',id,'de910000-0000-4000-8000-000000000011','TRANSFER',3,'Move books','de910000-0000-4000-8000-000000000012') from inventory_items where code='INV-BOOK'$$,'Paired transfer');
select is((select sum(delta) from inventory_entries where movement_id='de910000-0000-4000-8000-000000000023'),0::numeric,'Transfer net zero');
select is((select count(*) from inventory_entries where movement_id='de910000-0000-4000-8000-000000000023'),2::bigint,'Both transfer entries');
select lives_ok($$select post_inventory_movement('de910000-0000-4000-8000-000000000024',id,'de910000-0000-4000-8000-000000000011','ADJUSTMENT',-1,'Damaged copy counted') from inventory_items where code='INV-BOOK'$$,'Reasoned adjustment');
select throws_ok($$select post_inventory_movement('de910000-0000-4000-8000-000000000025',id,'de910000-0000-4000-8000-000000000011','OUTBOUND',5,'Too many') from inventory_items where code='INV-BOOK'$$,'P0001','Insufficient inventory','Negative stock rejected');
select is((select count(*) from inventory_movements where id='de910000-0000-4000-8000-000000000025'),0::bigint,'Rejected movement leaves no history');
select is((select closing from inventory_monthly_report('de910000-0000-4000-8000-000000000011',date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date) where code='INV-BOOK'),4::numeric,'Origin closing correct');
select is((select opening+inbound-outbound-closing from inventory_monthly_report('de910000-0000-4000-8000-000000000011',date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date) where code='INV-BOOK'),0::numeric,'Exact reconciliation');
select is((select closing from inventory_monthly_report('de910000-0000-4000-8000-000000000012',date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date) where code='INV-BOOK'),3::numeric,'Destination closing correct');
select throws_ok($$update inventory_entries set delta=100$$,'42501',null,'Client cannot edit entries');
select throws_ok($$delete from inventory_movements$$,'42501',null,'Client cannot erase history');
select set_config('request.jwt.claim.sub','de910000-0000-4000-8000-000000000002',true);
select is((select count(*) from inventory_items where code='INV-BOOK'),1::bigint,'Scoped inventory permission grants catalogue without branch-directory permission');
select is((select count(*) from inventory_entries where branch_id='de910000-0000-4000-8000-000000000012'),0::bigint,'Branch B entries hidden from A');
select is((select count(*) from inventory_movements where id='de910000-0000-4000-8000-000000000023'),0::bigint,'Transfer shared metadata requires both branches');
select throws_ok($$select * from inventory_monthly_report('de910000-0000-4000-8000-000000000012','2026-09-01')$$,'P0001','Unauthorized','Branch B report denied');
select throws_ok($$select post_inventory_movement('de910000-0000-4000-8000-000000000026',id,'de910000-0000-4000-8000-000000000011','TRANSFER',1,'Forbidden destination','de910000-0000-4000-8000-000000000012') from inventory_items where code='INV-BOOK'$$,'P0001','Unauthorized','Cross branch transfer denied');
select throws_ok($$select create_inventory_item('INV-OTHER','Other','Books','copy')$$,'P0001','Unauthorized','Scoped staff cannot change global catalogue');
reset role;
select throws_ok($$update inventory_entries set delta=100 where movement_id='de910000-0000-4000-8000-000000000021'$$,'P0001','Inventory history is immutable; post a new adjustment','Trigger protects history even from privileged update');
select set_config('request.jwt.claim.sub','de910000-0000-4000-8000-000000000001',true);
update profiles set status='INACTIVE' where id='de910000-0000-4000-8000-000000000002';
select set_config('request.jwt.claim.sub','de910000-0000-4000-8000-000000000002',true);
set local role authenticated;
select is((select count(*) from inventory_entries),0::bigint,'Inactive account denied');
select throws_ok($$select * from inventory_monthly_report('de910000-0000-4000-8000-000000000011','2026-09-01')$$,'P0001','Unauthorized','Inactive report denied');
reset role;
select set_config('request.jwt.claim.sub','de910000-0000-4000-8000-000000000001',true);
update profiles set status='ACTIVE' where id='de910000-0000-4000-8000-000000000002';
update user_roles set valid_until=now()-interval '1 second' where user_id='de910000-0000-4000-8000-000000000002';
select set_config('request.jwt.claim.sub','de910000-0000-4000-8000-000000000002',true);
set local role authenticated;
select is((select count(*) from inventory_entries),0::bigint,'Expired role denied');
select ok(not has_function_privilege('anon','public.post_inventory_movement(uuid,uuid,uuid,text,numeric,text,uuid)','EXECUTE'),'Anonymous posting denied');
select ok(not has_table_privilege('service_role','public.inventory_entries','INSERT'),'Service cannot bypass posting');
select * from finish();
rollback;
